"use client";

import * as React from "react";

import { GeoFlows, type FlowRegion, type RegionFlow } from "@/components/lumesec/geo-flows";

const regions: FlowRegion[] = [
  { id: "fra", label: "Frankfurt", lat: 50.11, lon: 8.68 },
  { id: "iad", label: "Ashburn", lat: 39.04, lon: -77.49 },
  { id: "sin", label: "Singapore", lat: 1.35, lon: 103.82 },
];

export function Example({ flows }: { flows: RegionFlow[] }) {
  const [region, setRegion] = React.useState<string | null>(null);
  return <GeoFlows regions={regions} flows={flows} value={region} onValueChange={setRegion} unit="Gbps" />;
}
